function telegramJsonParts({ body }) {
  if (
    !body ||
    typeof body !== "object" ||
    Array.isArray(body) ||
    !Number.isSafeInteger(body.update_id)
  )
    throw new Error("Expected a complete Telegram update");
  const senderId = body.message?.from?.id;
  if (!Number.isSafeInteger(senderId) || senderId <= 0)
    throw new Error("This debugger requires message.from.id and replies privately to that sender");
  const json = JSON.stringify(body, null, 2),
    segments = [];
  let text = "",
    html = "";
  for (const character of json) {
    const escaped =
      character === "&"
        ? "&amp;"
        : character === "<"
          ? "&lt;"
          : character === ">"
            ? "&gt;"
            : character;
    if (html.length + escaped.length > 4000) {
      segments.push({ text, html });
      text = "";
      html = "";
    }
    text += character;
    html += escaped;
  }
  if (text) segments.push({ text, html });
  const parts = segments.map((segment, index) => {
    const label = segments.length > 1 ? "Part " + (index + 1) + "/" + segments.length + "\n" : "";
    const html = "<pre>" + label + segment.html + "</pre>";
    if (html.length > 4096) throw new Error("The JSON part exceeds Telegram’s message limit");
    return { text: label + segment.text, html };
  });
  return { chatId: String(senderId), parts };
}

const items = $input.all();
if (items.length !== 1) throw new Error("Expected one Telegram update");
const result = telegramJsonParts({ body: items[0].json });
return result.parts.map((part, index) => ({
  json: { chatId: result.chatId, ...part, index: index + 1 },
  pairedItem: { item: 0 },
}));

const requests = $("Format the full update as JSON").all();
if (!Number.isInteger($runIndex) || $runIndex < 0 || $runIndex >= requests.length)
  throw new Error("Invalid JSON part index");
const request = requests[$runIndex].json;
const message = $json.result;
if (
  $json.ok !== true ||
  !message ||
  !Number.isSafeInteger(message.message_id) ||
  message.message_id <= 0 ||
  message.chat?.type !== "private" ||
  String(message.chat?.id) !== request.chatId ||
  message.text !== request.text
)
  throw new Error(
    "Telegram did not confirm the complete JSON part in the original sender’s private chat; sending may already have occurred",
  );
return { json: { part: request.index, message: $json } };
